/* Generado por etl_atenciones.py desde /mnt/user-data/uploads/atenciones_2026.xlsx · 100 atenciones · 97 empresas únicas */
USE ctrl_core_db;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @t := (SELECT id FROM tenants WHERE slug = 'unab-cde');
SET @u := (SELECT id FROM usuarios WHERE tenant_id=@t AND rol='admin_cde' AND activo=1 ORDER BY id LIMIT 1);
START TRANSACTION;
/* Usuario de sistema solo si aún no existe ningún admin_cde */
INSERT INTO usuarios (tenant_id,email,sso_subject,nombre_mostrar,rol)
SELECT @t,'sistema@cde.unab.local','sistema','Carga inicial','admin_cde' FROM DUAL WHERE @u IS NULL;
SET @u := (SELECT id FROM usuarios WHERE tenant_id=@t AND rol='admin_cde' AND activo=1 ORDER BY id LIMIT 1);
INSERT INTO migracion_lotes (tenant_id,usuario_id,archivo_nombre,estado,total_atenciones,total_empresas_unicas,filas_leidas)
VALUES (@t,@u,'atenciones_2026.xlsx','revisar',100,97,100);
SET @lote := LAST_INSERT_ID();

