/* Verificación: debe dar atenciones=100, empresas=97 */
SELECT (SELECT COUNT(*) FROM atenciones WHERE lote_id=@lote) AS atenciones,
       (SELECT COUNT(DISTINCT empresa_id) FROM atenciones WHERE lote_id=@lote) AS empresas;
